// Some portions generated by Claude Code

// A stored result travels to the row-store worker, and lives in IndexedDB, as text: each row written as JSON, one row
// per line. Copying one long string is far cheaper for the browser than copying the millions of small arrays and
// strings a large result is made of; with arrays, the worker could not keep up with the rows the server sent.

const test = require('node:test');
const assert = require('node:assert/strict');
const { MemoryWorker, loadApi } = require('./query-load-more-harness.js');
const { loadWorker, fakeIndexedDB } = require('./row-store-worker-harness.js');

const DATABASE_PREFIX = 'rdf4j-workbench-row-store:';
const BLOCK_ROWS = 1024;
const BLOCK_CHARS = 256 * 1024;
const XSD_INTEGER = 'http://www.w3.org/2001/XMLSchema#integer';

function compactRows(from, to) {
    return Array.from({ length: to - from }, (_, offset) => {
        const index = from + offset;
        return [[0, 'urn:text-blocks:' + index], [2, String(index), XSD_INTEGER]];
    });
}

function lines(rows) {
    return rows.map((row) => JSON.stringify(row)).join('\n');
}

/** A worker on a fresh fake IndexedDB, with a send that numbers requests and names the store. */
async function openStore(storeId) {
    const storage = fakeIndexedDB();
    const worker = loadWorker({ indexedDB: storage.indexedDB, IDBKeyRange: storage.IDBKeyRange });
    let requestId = 0;
    const send = (message) => worker.send(Object.assign({ requestId: ++requestId, storeId }, message));
    const created = await send({ op: 'create' });
    assert.equal(created.ok, true, created.error);
    const records = (name) => storage.databases.get(DATABASE_PREFIX + storeId).get(name).records
        .map((record) => record.value);
    return { send, records };
}

async function appendText(send, rows) {
    const response = await send({ op: 'append', text: lines(rows), rowCount: rows.length });
    assert.equal(response.ok, true, response.error);
    return response.count;
}

async function readRows(send, start, count) {
    const response = await send({ op: 'read', start, count });
    assert.equal(response.ok, true, response.error);
    assert.equal(typeof response.text, 'string', 'a read answers with the rows as JSON text');
    assert.equal(response.rows, undefined);
    return JSON.parse(response.text);
}

test('the row-store worker stores a text batch as blocks of whole rows and reads windows back as text', async () => {
    const { send, records } = await openStore('rows-text');
    const rows = compactRows(0, 3000);
    assert.equal(await appendText(send, rows), 3000);

    const [metadata] = records('stores');
    assert.equal(metadata.format, 'blocks-v2');
    assert.equal(metadata.count, 3000);
    const blocks = records('rows').sort((a, b) => a.index - b.index);
    assert.ok(blocks.length >= 3);
    let next = 0;
    for (const block of blocks) {
        assert.deepEqual(Object.keys(block).sort(), ['count', 'index', 'storeId', 'text']);
        assert.equal(block.index, next, 'blocks follow each other without gaps');
        assert.ok(block.count >= 1 && block.count <= BLOCK_ROWS);
        assert.ok(block.text.length <= BLOCK_CHARS);
        assert.equal(block.text, lines(rows.slice(block.index, block.index + block.count)));
        next += block.count;
    }
    assert.equal(next, 3000);

    assert.deepEqual(await readRows(send, 1020, 10), rows.slice(1020, 1030), 'a window across a block boundary');
    assert.deepEqual(await readRows(send, 2995, 10), rows.slice(2995), 'a window past the end is cut');
    assert.deepEqual(await readRows(send, 0, 0), []);
    assert.deepEqual(await readRows(send, 0, 3000), rows);
    assert.equal((await send({ op: 'count' })).count, 3000);
});

test('the row-store worker refuses a batch whose row count does not match its text', async () => {
    const { send } = await openStore('rows-refused');
    const mismatched = await send({ op: 'append', text: '[1]\n[2]', rowCount: 3 });
    assert.equal(mismatched.ok, false);
    const withoutText = await send({ op: 'append', rows: [[1]] });
    assert.equal(withoutText.ok, false, 'rows travel only as text');
    const empty = await send({ op: 'append', text: '', rowCount: 0 });
    assert.equal(empty.ok, true, empty.error);
    assert.equal(empty.count, 0);
    assert.equal((await send({ op: 'count' })).count, 0);
});

test('the row-store worker fills a partial last block, isolates a longer row and keeps blocks bounded', async () => {
    const { send, records } = await openStore('rows-bounded');
    const blocks = () => records('rows').sort((a, b) => a.index - b.index);
    const expected = compactRows(0, 10);
    await appendText(send, expected);
    await appendText(send, compactRows(10, 15));
    expected.push(...compactRows(10, 15));
    assert.deepEqual(blocks().map((block) => block.count), [15], 'a later append fills the partial last block');

    const longRow = [[2, 'x'.repeat(BLOCK_CHARS + 10)]];
    await appendText(send, [longRow]);
    expected.push(longRow);
    const wide = Array.from({ length: 5 }, (_, index) => [[2, String(index).repeat(100000)]]);
    await appendText(send, wide);
    expected.push(...wide);
    await appendText(send, compactRows(15, 1100));
    expected.push(...compactRows(15, 1100));

    for (const block of blocks()) {
        assert.ok(block.count <= BLOCK_ROWS);
        assert.ok(block.text.length <= BLOCK_CHARS || block.count === 1, 'only a single row may exceed the limit');
    }
    const longBlock = blocks().find((block) => block.text.length > BLOCK_CHARS);
    assert.equal(longBlock.count, 1, 'the longer row has a block of its own');
    assert.deepEqual(blocks().filter((block) => block.index > longBlock.index && block.index < 20)
        .map((block) => block.count), [2, 2], 'rows of 100,000 characters go two to a block');
    assert.deepEqual(await readRows(send, 0, expected.length), expected);
});

test('truncating text blocks keeps exactly the leading rows, and later appends continue after them', async () => {
    const { send, records } = await openStore('rows-truncated');
    const rows = compactRows(0, 2000);
    await appendText(send, rows);
    const truncated = await send({ op: 'truncate', count: 1500 });
    assert.equal(truncated.ok, true, truncated.error);
    assert.equal(truncated.count, 1500);
    assert.deepEqual(await readRows(send, 0, 2000), rows.slice(0, 1500));
    const [metadata] = records('stores');
    assert.equal(metadata.count, 1500);
    assert.equal(metadata.tailStart + metadata.tailRows, 1500);

    const more = compactRows(5000, 5010);
    assert.equal(await appendText(send, more), 1510);
    assert.deepEqual(await readRows(send, 1495, 20), rows.slice(1495, 1500).concat(more));
    assert.equal((await send({ op: 'truncate', count: 0 })).count, 0);
    assert.deepEqual(await readRows(send, 0, 10), []);
    assert.equal(await appendText(send, more.slice(0, 2)), 2);
    assert.deepEqual(await readRows(send, 0, 10), more.slice(0, 2));
});

test('rows come back unchanged through the text format', async () => {
    const { send } = await openStore('rows-lossless');
    const rows = [
        [[0, 'urn:a'], null, [1, 'b0', 'scope-1'], [2, 'line one\nline two\r\n', null, 'en']],
        [[2, 'quote " backslash \\ tab \t', 'urn:dt'], [2, 'مرحبا 🙂 Aé𝄞', null, 'ar', 'rtl']],
        [[2, 'lone high:\ud800 low:\udc00 nul:\u0000 sep:  ', 'urn:control']],
        [[3, [0, 'urn:s'], [0, 'urn:p'], [3, [1, 'nested', 'scope-2'], [0, 'urn:n'], [2, 'hola', null, 'es']]]],
        [{ kind: 'literal', value: 'legacy\nterm', datatype: 'http://www.w3.org/2001/XMLSchema#string' }, null],
        [[2, '', null], [2, '12', XSD_INTEGER], [2, '1.5e3', 'http://www.w3.org/2001/XMLSchema#double']]
    ];
    assert.equal(await appendText(send, rows), rows.length);
    assert.deepEqual(await readRows(send, 0, rows.length), rows);
    assert.deepEqual(await readRows(send, 2, 1), rows.slice(2, 3));
});

/** A worker that speaks the text protocol and keeps the parsed rows, recording what the page posts. */
class TextProtocolWorker extends MemoryWorker {
    postMessage(message) {
        this.messages.push(message);
        queueMicrotask(() => {
            const response = { requestId: message.requestId, ok: true, storeId: message.storeId };
            if (message.op === 'append') {
                if (typeof message.text !== 'string') {
                    response.ok = false;
                    response.error = 'A row batch is required.';
                } else if (message.rowCount > 0) {
                    this.rows.push(...message.text.split('\n').map((line) => JSON.parse(line)));
                }
            } else if (message.op === 'read') {
                response.text = JSON.stringify(this.rows.slice(message.start, message.start + message.count));
            } else if (message.op === 'truncate') {
                this.rows.length = message.count;
            } else if (message.op === 'dispose') {
                this.rows = [];
                response.disposed = true;
            }
            response.count = this.rows.length;
            for (const callback of this.listeners.get('message') || []) callback({ data: response });
        });
    }
}

async function moved(store, rounds = 100) {
    for (let index = 0; index < rounds && store.inMemory; index++) await new Promise((resolve) => setImmediate(resolve));
}

test('a stored result posts each batch to its worker as one text of JSON rows and reads rows back from text',
    async () => {
        const { api } = loadApi();
        const worker = new TextProtocolWorker();
        const store = await api.createRowStore({ workerFactory: () => worker, spillRowLimit: 0 });
        const first = compactRows(0, 3);
        assert.equal(await store.append(first), 3);
        await moved(store);
        assert.equal(store.inMemory, false);
        const second = [[[2, 'two\nlines', null, 'en']], [null]];
        assert.equal(await store.append(second), 5);

        const appends = worker.messages.filter((message) => message.op === 'append');
        assert.ok(appends.length >= 2);
        for (const message of appends) {
            assert.equal(typeof message.text, 'string');
            assert.equal(Object.prototype.hasOwnProperty.call(message, 'rows'), false, 'no row arrays are posted');
            assert.equal(message.text.split('\n').length, message.rowCount);
        }
        assert.equal(appends.at(-1).text, lines(second));
        // Rows parsed in the page's realm: compare their JSON.
        assert.deepEqual(JSON.parse(JSON.stringify(await store.read(1, 10))), first.slice(1).concat(second));
        await store.dispose();
    });

test('encodeRowBatch writes each row as JSON on a line of its own', () => {
    const { api } = loadApi();
    const rows = [[[0, 'urn:a'], null], [[2, 'a\nb', null, 'en']], []];
    const text = api.encodeRowBatch(rows);
    assert.equal(text, '[[0,"urn:a"],null]\n[[2,"a\\nb",null,"en"]]\n[]');
    assert.deepEqual(text.split('\n').map((line) => JSON.parse(line)), rows);
    assert.equal(api.encodeRowBatch([]), '');
});
